window.__DAILY_CHUNKS__[6] = [{"week":46,"level":"B2","theme":"写作攻坚：250 词论说文与正式信函","days":[{"day":1,"theme":"词汇 · 文化与艺术","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：文化与艺术","body":"文化与艺术（La culture et les arts）是这一周要反复见面的主题域。打开 vocab.html#t23，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span>（上涨）、<span class=\"fr\" data-fr=\"une baisse\">une baisse</span>（下降）、<span class=\"fr\" data-fr=\"une décision\">une décision</span>（决定）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t23","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5021","level":"B2","skill":"vocab","prompt":"« une augmentation » 的意思是？","options":["上涨","减少","权威"],"answer":"上涨","explain":"augmentation 是上涨、增加；diminution 是减少；autorité 是权威。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"vocab","title":"搭配与辨析：une analyse / une proposition","body":"<span class=\"fr\" data-fr=\"une analyse\">une analyse</span>（分析）与 <span class=\"fr\" data-fr=\"une proposition\">une proposition</span>（提议）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t23","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5022","level":"B2","skill":"vocab","prompt":"« une baisse » 的意思是？","options":["下降","底部","低音"],"answer":"下降","explain":"baisse 是下降；bas 是底部；basse 是低音。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"listen","title":"听音辨词：文化与艺术","body":"打开 对话页的 d39 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"améliorer\">améliorer</span>（改善）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d39","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"La forte augmentation des prix inquiète les ménages.\">La forte augmentation des prix inquiète les ménages.</span>（物价大幅上涨让家庭担忧。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：文化与艺术 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span> <span class=\"fr\" data-fr=\"une baisse\">une baisse</span> <span class=\"fr\" data-fr=\"une décision\">une décision</span> <span class=\"fr\" data-fr=\"une analyse\">une analyse</span> <span class=\"fr\" data-fr=\"une proposition\">une proposition</span> <span class=\"fr\" data-fr=\"améliorer\">améliorer</span>。说不出来的词立刻回到 vocab.html#t23 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t23","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]}]},{"day":2,"theme":"语法 · 动词 → 名词转换","type":"grammar","steps":[{"type":"grammar","title":"语法点：动词 → 名词转换","body":"【动词 → 名词转换】B2 写作的重点是名词化（décider 变 la décision、augmenter 变 l'augmentation）、无人称结构与分词从句，同时避免 donc、puis 反复出现。连接词要多样化：列举用 d'une part… d'autre part，补充用 en outre、par ailleurs，转折用 or、toutefois。 例句：<span class=\"fr\" data-fr=\"La forte augmentation des prix inquiète les ménages.\">La forte augmentation des prix inquiète les ménages.</span>（物价大幅上涨让家庭担忧。）；<span class=\"fr\" data-fr=\"D'une part le coût baisse, d'autre part la qualité se dégrade.\">D'une part le coût baisse, d'autre part la qualité se dégrade.</span>（一方面成本下降，另一方面质量在下降。）。对照 grammar-b1b2.html#nom-verbes 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#nom-verbes","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5021","level":"B2","skill":"grammar","prompt":"« décider » 的名词化形式是？","options":["la décision","le décidement","la décidance"],"answer":"la décision","explain":"这类动词常以 -tion 或 -sion 结尾构成名词：décider 变 la décision。","source":"语法 · 名词化"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#nom-verbes 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"La forte augmentation des prix inquiète les ménages.\">La forte augmentation des prix inquiète les ménages.</span>（物价大幅上涨让家庭担忧。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#nom-verbes","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5022","level":"B2","skill":"grammar","prompt":"« augmenter » 的名词化形式是？","options":["l'augmentation","l'augmentement","l'augmentité"],"answer":"l'augmentation","explain":"动词名词化的常见后缀有 -tion、-ment、-ance、-ité，augmenter 对应 l'augmentation。","source":"语法 · 名词化"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"read","title":"在短文里找动词 → 名词转换","body":"在 grammar-b1b2.html#nom-verbes 的例句和章末小测里挑 5 句，圈出所有属于「动词 → 名词转换」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#nom-verbes","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"La forte augmentation des prix inquiète les ménages.\">La forte augmentation des prix inquiète les ménages.</span>（物价大幅上涨让家庭担忧。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，动词 → 名词转换 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：书面语体特征","body":"今天再回 grammar-b1b2.html#nom-style 看一遍 书面语体特征，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#nom-style","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:名词化"}]}]},{"day":3,"theme":"精听 · 对话页的 d39 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d39 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d39","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5011","level":"B2","skill":"listening","prompt":"朗读自己文章的主要目的是？","options":["发现长句与不顺的衔接","检查字数","练习发音"],"answer":"发现长句与不顺的衔接","explain":"朗读能把书面语里过长或断裂的句子暴露出来。","source":"写作 · 自查方法"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:自行车道"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：朗读并回听自己的文章，定位「能读但不地道」的句子。","src":"dialogue.html#d39","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span>（上涨）、<span class=\"fr\" data-fr=\"une baisse\">une baisse</span>（下降）、<span class=\"fr\" data-fr=\"une décision\">une décision</span>（决定）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t23","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「动词 → 名词转换 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d39","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 250 词论说文与正式信函","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：把文章脱稿讲 4 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5006","level":"B2","skill":"speaking","prompt":"把书面文章脱稿讲出来，最难的是？","options":["把名词化结构还原成动词句","记住字数","保持语速"],"answer":"把名词化结构还原成动词句","explain":"口语需要把名词化结构还原为动词句，这正是语域转换训练的核心。","source":"口语 · 语域转换"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:人工智能"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d39 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、动词 → 名词转换 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d39","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une analyse\">une analyse</span>（分析）、<span class=\"fr\" data-fr=\"une proposition\">une proposition</span>（提议）、<span class=\"fr\" data-fr=\"améliorer\">améliorer</span>（改善）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t23 再看一遍例句。","src":"vocab.html#t23","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 250 词论说文与正式信函","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：对比自己的文章与 22 分范文，列出 10 处可替换表达。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5011","level":"B2","skill":"reading","prompt":"与 22 分范文对比时，最该找的是？","options":["可替换的更地道表达","字数差距","主题差异"],"answer":"可替换的更地道表达","explain":"把范文的升级表达替换进自己的文章，是最快的提分方式。","source":"考试 · 范文研读"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:人工智能"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span>（上涨）、<span class=\"fr\" data-fr=\"une baisse\">une baisse</span>（下降）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t23","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#nom-verbes，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#nom-verbes","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「动词 → 名词转换」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 250 词论说文与正式信函","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：按考试时间 60 分钟完成 3 篇文章（2 篇论述加 1 封正式信函），全部限时。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5006","level":"B2","skill":"writing","prompt":"限时写作的时间分配建议是？","options":["5 分钟提纲、45 分钟写作、10 分钟检查","全部时间写作","先写结论"],"answer":"5 分钟提纲、45 分钟写作、10 分钟检查","explain":"留出提纲与检查时间，能显著减少结构与低级错误。","source":"写作 · 应试策略"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:投诉信"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#nom-verbes，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#nom-verbes","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「动词 → 名词转换」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span>（上涨）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 250 词论说文与正式信函","type":"review","steps":[{"type":"review","title":"本周回顾：写作攻坚：250 词论说文与正式信函","body":"这一周围绕「写作攻坚：250 词论说文与正式信函」展开：语法主线是 动词 → 名词转换，词汇主线是 文化与艺术。先用 3 句话口头复述本周学了什么，再打开日历页第 46 周清单逐条核对里程碑。","src":"calendar.html#wk-46","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"review","title":"语法复盘：动词 → 名词转换","body":"从 grammar-b1b2.html#nom-verbes 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#nom-verbes","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"review","title":"词汇自测：文化与艺术","body":"遮住中文看 vocab.html#t23 的 6 个核心词：<span class=\"fr\" data-fr=\"une augmentation\">une augmentation</span> <span class=\"fr\" data-fr=\"une baisse\">une baisse</span> <span class=\"fr\" data-fr=\"une décision\">une décision</span> <span class=\"fr\" data-fr=\"une analyse\">une analyse</span> <span class=\"fr\" data-fr=\"une proposition\">une proposition</span> <span class=\"fr\" data-fr=\"améliorer\">améliorer</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t23","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5023","level":"B2","skill":"vocab","prompt":"« une proposition » 的意思是？","options":["提议","比例","目的"],"answer":"提议","explain":"proposition 是提议；proportion 是比例；propos 是话语。","source":"词汇 · 论述"},{"id":"q-vocab-b2-5024","level":"B2","skill":"vocab","prompt":"« une analyse » 的意思是？","options":["分析","类似","年鉴"],"answer":"分析","explain":"analyse 是分析；analogue 是类似的；annale 是年鉴。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d39","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5012","level":"B2","skill":"listening","prompt":"听到 /dyn paʁ, dotʁ paʁ/ 时表示？","options":["一方面、另一方面","一个部分、另一个部分","一个地方、另一个地方"],"answer":"一方面、另一方面","explain":"d'une part… d'autre part… 是书面论述里列举两方的固定结构。","source":"语法 · 逻辑连接词"},{"id":"q-read-b2-5012","level":"B2","skill":"reading","prompt":"名词化的主要作用是？","options":["压缩句子、提升语域","让句子变长","增加情感"],"answer":"压缩句子、提升语域","explain":"名词化把从句压缩成名词短语，同时提高语域，是书面语的核心手段。","source":"语法 · 书面语体"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 动词 → 名词转换 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#nom-verbes 再核对一次。","src":"grammar-b1b2.html#nom-style","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5023","level":"B2","skill":"grammar","prompt":"「物价上涨让家庭担忧」的书面表达是？","options":["La hausse des prix inquiète les ménages.","Les prix montent et ça inquiète les gens.","Les prix, ça monte, ça inquiète."],"answer":"La hausse des prix inquiète les ménages.","explain":"名词化主语加抽象动词构成典型书面语，后两句偏口语。","source":"语法 · 名词化"},{"id":"q-gram-b2-5024","level":"B2","skill":"grammar","prompt":"下列哪句连接词最丰富？","options":["D'une part les coûts baissent ; en revanche la qualité se dégrade.","Donc les coûts baissent et donc la qualité change.","Les coûts baissent, la qualité change."],"answer":"D'une part les coûts baissent ; en revanche la qualité se dégrade.","explain":"连接词多样且逻辑清晰、避免 donc 反复出现，是 B2 写作的评分点。","source":"语法 · 逻辑连接词"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":47,"level":"B2","theme":"被动、使役与名词化：书面语体进阶","days":[{"day":1,"theme":"词汇 · 抽象概念与逻辑","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：抽象概念与逻辑","body":"本周词汇主战场是抽象概念与逻辑（Les notions abstraites et la logique）。先到 vocab.html#t24 把词表扫一遍，把 <span class=\"fr\" data-fr=\"laisser\">laisser</span>（任由；让）、<span class=\"fr\" data-fr=\"une hausse\">une hausse</span>（上涨）、<span class=\"fr\" data-fr=\"un mécontentement\">un mécontentement</span>（不满）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t24","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5025","level":"B2","skill":"vocab","prompt":"« un mécontentement » 的意思是？","options":["不满","不高兴的表情","失望"],"answer":"不满","explain":"mécontentement 指（一群人的）不满；déception 是失望。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"vocab","title":"搭配与辨析：la mise en œuvre / un constat","body":"把 <span class=\"fr\" data-fr=\"la mise en œuvre\">la mise en œuvre</span>（实施）和 <span class=\"fr\" data-fr=\"un constat\">un constat</span>（观察结论）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t24","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5026","level":"B2","skill":"vocab","prompt":"« la mise en œuvre » 的意思是？","options":["实施","登上舞台","放下"],"answer":"实施","explain":"mise en œuvre 表示实施、落实；mise en scène 是舞台呈现。","source":"词汇 · 政治"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"listen","title":"听音辨词：抽象概念与逻辑","body":"打开 对话页的 d31 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"faire faire\">faire faire</span>（让……做）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d31","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Le directeur a fait réviser le rapport par son assistante.\">Le directeur a fait réviser le rapport par son assistante.</span>（主管让助理修改了报告。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：抽象概念与逻辑 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"laisser\">laisser</span> <span class=\"fr\" data-fr=\"une hausse\">une hausse</span> <span class=\"fr\" data-fr=\"un mécontentement\">un mécontentement</span> <span class=\"fr\" data-fr=\"la mise en œuvre\">la mise en œuvre</span> <span class=\"fr\" data-fr=\"un constat\">un constat</span> <span class=\"fr\" data-fr=\"faire faire\">faire faire</span>。说不出来的词立刻回到 vocab.html#t24 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t24","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]}]},{"day":2,"theme":"语法 · 使役结构","type":"grammar","steps":[{"type":"grammar","title":"语法点：使役结构","body":"【使役结构】使役结构 faire / laisser / voir / entendre 加不定式表示让、任由、看见、听见某人做某事；用 faire 时施动者可用 à 或 par 引出，且 faire 的过去分词永远不变。名词化与「动词句换名词句」的互换，是书面语体进阶的核心工具。 例句：<span class=\"fr\" data-fr=\"Le directeur a fait réviser le rapport par son assistante.\">Le directeur a fait réviser le rapport par son assistante.</span>（主管让助理修改了报告。）；<span class=\"fr\" data-fr=\"L'augmentation des prix provoque le mécontentement.\">L'augmentation des prix provoque le mécontentement.</span>（物价上涨引发了不满。）。对照 grammar-b1b2.html#causatif 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#causatif","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5025","level":"B2","skill":"grammar","prompt":"「他让助理修改报告」应说？","options":["Il a fait réviser le rapport par son assistante.","Il a fait réviser le rapport à par son assistante.","Il a faire réviser le rapport."],"answer":"Il a fait réviser le rapport par son assistante.","explain":"使役结构是 faire 加不定式，施动者可用 par 引出。","source":"语法 · 使役结构"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 使役结构 的规则和两个例句，再打开 grammar-b1b2.html#causatif 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#causatif","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5026","level":"B2","skill":"grammar","prompt":"« voir » 作使役动词时后接？","options":["不定式","虚拟式","过去分词"],"answer":"不定式","explain":"voir、entendre、laisser 加不定式表示看见、听见、任由某人做某事。","source":"语法 · 使役结构"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"read","title":"在短文里找使役结构","body":"在 grammar-b1b2.html#causatif 的例句和章末小测里挑 5 句，圈出所有属于「使役结构」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#causatif","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Le directeur a fait réviser le rapport par son assistante.\">Le directeur a fait réviser le rapport par son assistante.</span>（主管让助理修改了报告。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，使役结构 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：名词化与书面语体","body":"今天再回 grammar-b1b2.html#nominalisation 看一遍 名词化与书面语体，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#nominalisation","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:名词化"}]}]},{"day":3,"theme":"精听 · 对话页的 d31 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d31 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d31","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5013","level":"B2","skill":"listening","prompt":"演讲中听到 « la mise en place de mesures » 应还原为？","options":["on met en place des mesures","des mesures mettent en place","la place met des mesures"],"answer":"on met en place des mesures","explain":"名词化结构还原时要补出动作的施动者，常用 on 或具体主语。","source":"语法 · 名词化"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:四天工作制"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听正式演讲，把名词化结构还原成动词句。","src":"dialogue.html#d31","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"laisser\">laisser</span>（任由；让）、<span class=\"fr\" data-fr=\"une hausse\">une hausse</span>（上涨）、<span class=\"fr\" data-fr=\"un mécontentement\">un mécontentement</span>（不满）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t24","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「使役结构 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d31","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 书面语体进阶","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：同一内容说两遍：一遍口语化、一遍书面语化，感受语域差别。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5007","level":"B2","skill":"speaking","prompt":"同一内容说两遍时，书面语化的关键是？","options":["用名词化与无人称结构","放慢语速","增加停顿"],"answer":"用名词化与无人称结构","explain":"语域转换靠名词化、无人称结构与更高阶的词汇，而不是语速。","source":"口语 · 语域转换"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:心理健康"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d31 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、使役结构 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d31","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"la mise en œuvre\">la mise en œuvre</span>（实施）、<span class=\"fr\" data-fr=\"un constat\">un constat</span>（观察结论）、<span class=\"fr\" data-fr=\"faire faire\">faire faire</span>（让……做）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t24 再看一遍例句。","src":"vocab.html#t24","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 书面语体进阶","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 1200 词官方报告或学术摘要，标出所有名词化结构。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5013","level":"B2","skill":"reading","prompt":"官方报告里名词化结构的标志是？","options":["-tion、-ment、-ance 结尾的抽象名词作主语","大量动词变位","大量感叹句"],"answer":"-tion、-ment、-ance 结尾的抽象名词作主语","explain":"抽象名词作主语是公文与学术文本的典型特征。","source":"语法 · 名词化"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:远程办公"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「使役结构」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"laisser\">laisser</span>（任由；让）、<span class=\"fr\" data-fr=\"une hausse\">une hausse</span>（上涨）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t24","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#causatif，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#causatif","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「使役结构」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 书面语体进阶","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：把 15 个口语句改写为书面语，再反转一次。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5007","level":"B2","skill":"writing","prompt":"把口语句改写为书面语时，最常用的操作是？","options":["动词句变名词短语作主语","增加口语词","缩短句子"],"answer":"动词句变名词短语作主语","explain":"名词化是口语转书面语最常用的操作。","source":"写作 · 语域转换"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:四天工作制"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#causatif，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#causatif","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「使役结构」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"laisser\">laisser</span>（任由；让）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 书面语体进阶","type":"review","steps":[{"type":"review","title":"本周回顾：被动、使役与名词化：书面语体进阶","body":"这一周围绕「被动、使役与名词化：书面语体进阶」展开：语法主线是 使役结构，词汇主线是 抽象概念与逻辑。先用 3 句话口头复述本周学了什么，再打开日历页第 47 周清单逐条核对里程碑。","src":"calendar.html#wk-47","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"语法复盘：使役结构","body":"从 grammar-b1b2.html#causatif 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#causatif","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:名词化"}]},{"type":"review","title":"词汇自测：抽象概念与逻辑","body":"遮住中文看 vocab.html#t24 的 6 个核心词：<span class=\"fr\" data-fr=\"laisser\">laisser</span> <span class=\"fr\" data-fr=\"une hausse\">une hausse</span> <span class=\"fr\" data-fr=\"un mécontentement\">un mécontentement</span> <span class=\"fr\" data-fr=\"la mise en œuvre\">la mise en œuvre</span> <span class=\"fr\" data-fr=\"un constat\">un constat</span> <span class=\"fr\" data-fr=\"faire faire\">faire faire</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t24","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5027","level":"B2","skill":"vocab","prompt":"« laisser » 的意思是？","options":["任由；让","租借","抬起"],"answer":"任由；让","explain":"laisser 表示任由、让；louer 是租借；lever 是抬起。","source":"词汇 · 高频动词"},{"id":"q-vocab-b2-5028","level":"B2","skill":"vocab","prompt":"« un constat » 的意思是？","options":["观察结论","警方笔录","建筑"],"answer":"观察结论","explain":"constat 指观察得出的结论，也指现场笔录；construction 是建筑。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d31","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5014","level":"B2","skill":"listening","prompt":"听到 « on constate une hausse » 时，名词化核心词是？","options":["une hausse","on","constate"],"answer":"une hausse","explain":"名词化的核心是抽象名词 une hausse，动词 constater 提供判断。","source":"语法 · 名词化"},{"id":"q-read-b2-5014","level":"B2","skill":"reading","prompt":"使役句里 faire 的过去分词要？","options":["永远不变","与宾语配合","与主语配合"],"answer":"永远不变","explain":"faire 加不定式时，faire 的过去分词永远不变形，这是它与普通动词不同的地方。","source":"语法 · 使役结构"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 使役结构 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#causatif 再核对一次。","src":"grammar-b1b2.html#nominalisation","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5027","level":"B2","skill":"grammar","prompt":"「价格上涨引发不满」的书面表达是？","options":["La hausse des prix suscite le mécontentement.","Les prix montent et les gens sont pas contents.","Les prix, ça monte."],"answer":"La hausse des prix suscite le mécontentement.","explain":"名词化主语加准确动词构成书面语体，后两句偏口语。","source":"语法 · 名词化"},{"id":"q-gram-b2-5028","level":"B2","skill":"grammar","prompt":"「我听见他上楼了」应说？","options":["Je l'ai entendu monter.","Je l'ai entendu qu'il monte.","Je l'ai entendu de monter."],"answer":"Je l'ai entendu monter.","explain":"entendre 加不定式构成感知使役结构，不能接 que 从句。","source":"语法 · 使役结构"},{"ref":"bank:grammar:B2:名词化"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":48,"level":"B2","theme":"文化、媒体与长篇听力","days":[{"day":1,"theme":"词汇 · 文化与艺术","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：文化与艺术","body":"文化与艺术（La culture et les arts）是这一周要反复见面的主题域。打开 vocab.html#t23，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span>（作品）、<span class=\"fr\" data-fr=\"un réalisateur\">un réalisateur</span>（导演）、<span class=\"fr\" data-fr=\"une intrigue\">une intrigue</span>（情节）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t23","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5029","level":"B2","skill":"vocab","prompt":"« une intrigue » 的意思是？","options":["情节","阴谋集团","复杂"],"answer":"情节","explain":"intrigue 在文艺语境里指情节，也可以指阴谋。","source":"词汇 · 文化"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"vocab","title":"搭配与辨析：un personnage / émouvant","body":"<span class=\"fr\" data-fr=\"un personnage\">un personnage</span>（人物）与 <span class=\"fr\" data-fr=\"émouvant\">émouvant</span>（感人的）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t23","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5030","level":"B2","skill":"vocab","prompt":"« émouvant » 的意思是？","options":["感人的","移动的","易怒的"],"answer":"感人的","explain":"émouvant 是感人的；mouvant 是移动的； irritable 是易怒的。","source":"词汇 · 文化"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"listen","title":"听音辨词：文化与艺术","body":"打开 对话页的 d39 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"une critique\">une critique</span>（评论）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d39","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Ce qui frappe dans ce film, c'est la sobriété du jeu.\">Ce qui frappe dans ce film, c'est la sobriété du jeu.</span>（这部电影让人印象深刻的是表演的克制。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：文化与艺术 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span> <span class=\"fr\" data-fr=\"un réalisateur\">un réalisateur</span> <span class=\"fr\" data-fr=\"une intrigue\">une intrigue</span> <span class=\"fr\" data-fr=\"un personnage\">un personnage</span> <span class=\"fr\" data-fr=\"émouvant\">émouvant</span> <span class=\"fr\" data-fr=\"une critique\">une critique</span>。说不出来的词立刻回到 vocab.html#t23 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t23","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]}]},{"day":2,"theme":"语法 · 动词加介词搭配表","type":"grammar","steps":[{"type":"grammar","title":"语法点：动词加介词搭配表","body":"【动词加介词搭配表】这一周不学新点，把已学结构整理成一张 A4 速查表（时态、虚拟式触发词、连接词、代词）。文化评论常用评价性表达：ce qui frappe、on ne peut qu'admirer、se distinguer par；动词加介词的搭配（s'intéresser à、se distinguer par、tenir à）也要一并核对。 例句：<span class=\"fr\" data-fr=\"Ce qui frappe dans ce film, c'est la sobriété du jeu.\">Ce qui frappe dans ce film, c'est la sobriété du jeu.</span>（这部电影让人印象深刻的是表演的克制。）；<span class=\"fr\" data-fr=\"L'œuvre se distingue par son originalité.\">L'œuvre se distingue par son originalité.</span>（这部作品以独创性见长。）。对照 grammar-b1b2.html#verbes-prepositions 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#verbes-prepositions","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5029","level":"B2","skill":"grammar","prompt":"「这部作品以独创性见长」应说？","options":["L'œuvre se distingue par son originalité.","L'œuvre se distingue de son originalité.","L'œuvre distingue par son originalité."],"answer":"L'œuvre se distingue par son originalité.","explain":"se distinguer par 表示以某特点见长，介词固定用 par。","source":"语法 · 动词加介词"},{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#verbes-prepositions 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Ce qui frappe dans ce film, c'est la sobriété du jeu.\">Ce qui frappe dans ce film, c'est la sobriété du jeu.</span>（这部电影让人印象深刻的是表演的克制。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#verbes-prepositions","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5030","level":"B2","skill":"grammar","prompt":"「我对音乐感兴趣」应说？","options":["Je m'intéresse à la musique.","Je m'intéresse de la musique.","J'intéresse la musique."],"answer":"Je m'intéresse à la musique.","explain":"s'intéresser à 是固定搭配，而且必须带自反代词。","source":"语法 · 动词加介词"},{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"read","title":"在短文里找动词加介词搭配表","body":"在 grammar-b1b2.html#verbes-prepositions 的例句和章末小测里挑 5 句，圈出所有属于「动词加介词搭配表」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#verbes-prepositions","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Ce qui frappe dans ce film, c'est la sobriété du jeu.\">Ce qui frappe dans ce film, c'est la sobriété du jeu.</span>（这部电影让人印象深刻的是表演的克制。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，动词加介词搭配表 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：B2 高频固定搭配","body":"今天再回 grammar-b1b2.html#expressions-b2 看一遍 B2 高频固定搭配，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#expressions-b2","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:固定搭配"}]}]},{"day":3,"theme":"精听 · 对话页的 d39 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d39 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d39","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5015","level":"B2","skill":"listening","prompt":"长篇听力训练的核心目标是？","options":["听懂主旨与要点","听懂每个词","记住所有数字"],"answer":"听懂主旨与要点","explain":"长篇语料的训练目标是抓主旨与要点，逐词理解会跟不上。","source":"考试 · 听力策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:一次性塑料"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：每天 45 分钟长篇音频（纪录片、访谈、播客），要求听懂 80% 的主旨与要点。","src":"dialogue.html#d39","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span>（作品）、<span class=\"fr\" data-fr=\"un réalisateur\">un réalisateur</span>（导演）、<span class=\"fr\" data-fr=\"une intrigue\">une intrigue</span>（情节）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t23","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「动词加介词搭配表 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d39","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 文化、媒体与长篇听力","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就一部电影或一本书做 5 分钟推荐式陈述。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5008","level":"B2","skill":"speaking","prompt":"推荐式陈述的结构建议是？","options":["作品背景、两三个亮点、个人评价","只讲剧情","只讲导演生平"],"answer":"作品背景、两三个亮点、个人评价","explain":"推荐式陈述要有背景、亮点与评价三层，才显得有观点。","source":"口语 · 陈述"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:人工智能"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d39 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、动词加介词搭配表 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d39","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un personnage\">un personnage</span>（人物）、<span class=\"fr\" data-fr=\"émouvant\">émouvant</span>（感人的）、<span class=\"fr\" data-fr=\"une critique\">une critique</span>（评论）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t23 再看一遍例句。","src":"vocab.html#t23","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 文化、媒体与长篇听力","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 1500 词文化评论，标出评价性表达。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5015","level":"B2","skill":"reading","prompt":"文化评论里的评价性表达作用是？","options":["表明作者的立场与审美判断","提供事实信息","凑字数"],"answer":"表明作者的立场与审美判断","explain":"评价性表达是文化评论文体的核心，也是考官关注的语域特征。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:人工智能"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span>（作品）、<span class=\"fr\" data-fr=\"un réalisateur\">un réalisateur</span>（导演）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t23","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#verbes-prepositions，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#verbes-prepositions","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「动词加介词搭配表」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 文化、媒体与长篇听力","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词文化评论（含评价与论据）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5008","level":"B2","skill":"writing","prompt":"写文化评论时，论据应该？","options":["引用作品的具体细节","只写感受","只复述剧情"],"answer":"引用作品的具体细节","explain":"评论要用作品细节支撑评价，避免空泛赞美。","source":"写作 · 文化评论"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:投诉信"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#verbes-prepositions，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#verbes-prepositions","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「动词加介词搭配表」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span>（作品）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 文化、媒体与长篇听力","type":"review","steps":[{"type":"review","title":"本周回顾：文化、媒体与长篇听力","body":"这一周围绕「文化、媒体与长篇听力」展开：语法主线是 动词加介词搭配表，词汇主线是 文化与艺术。先用 3 句话口头复述本周学了什么，再打开日历页第 48 周清单逐条核对里程碑。","src":"calendar.html#wk-48","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"review","title":"语法复盘：动词加介词搭配表","body":"从 grammar-b1b2.html#verbes-prepositions 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#verbes-prepositions","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"review","title":"词汇自测：文化与艺术","body":"遮住中文看 vocab.html#t23 的 6 个核心词：<span class=\"fr\" data-fr=\"une œuvre\">une œuvre</span> <span class=\"fr\" data-fr=\"un réalisateur\">un réalisateur</span> <span class=\"fr\" data-fr=\"une intrigue\">une intrigue</span> <span class=\"fr\" data-fr=\"un personnage\">un personnage</span> <span class=\"fr\" data-fr=\"émouvant\">émouvant</span> <span class=\"fr\" data-fr=\"une critique\">une critique</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t23","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5031","level":"B2","skill":"vocab","prompt":"« un réalisateur » 的意思是？","options":["导演","实现者","现实主义者"],"answer":"导演","explain":"réalisateur 在影视语境里指导演；réaliste 是现实主义者。","source":"词汇 · 文化"},{"id":"q-vocab-b2-5032","level":"B2","skill":"vocab","prompt":"« un personnage » 的意思是？","options":["人物","人格面具","重要的人"],"answer":"人物","explain":"personnage 指作品中的人物，也可以指重要人物。","source":"词汇 · 文化"},{"ref":"bank:vocab:A2:文化与艺术"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d39","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5016","level":"B2","skill":"listening","prompt":"纪录片听力中，最需要抓的是？","options":["论证脉络与关键数据","每个形容词","背景音乐"],"answer":"论证脉络与关键数据","explain":"纪录片常靠论证脉络与数据支撑观点，这两项是理解的关键。","source":"考试 · 听力策略"},{"id":"q-read-b2-5016","level":"B2","skill":"reading","prompt":"「ce qui frappe, c'est…」的作用是？","options":["引出最突出的观察","引出让步","引出结论"],"answer":"引出最突出的观察","explain":"ce qui frappe, c'est 用于引出最引人注目的特点。","source":"语法 · 强调结构"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 动词加介词搭配表 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#verbes-prepositions 再核对一次。","src":"grammar-b1b2.html#expressions-b2","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5031","level":"B2","skill":"grammar","prompt":"« tenir à » 后面接？","options":["名词或不定式","虚拟式从句","过去分词"],"answer":"名词或不定式","explain":"tenir à 后接名词或不定式，表示珍视、坚持。","source":"语法 · 动词加介词"},{"id":"q-gram-b2-5032","level":"B2","skill":"grammar","prompt":"速查表里「虚拟式触发词」应包含？","options":["il faut que、bien que、douter que","hier、demain、aujourd'hui","le、la、les"],"answer":"il faut que、bien que、douter que","explain":"速查表要按功能归类：意志、必要、情感、怀疑、连词、最高级。","source":"语法 · 复习方法"},{"ref":"bank:grammar:B2:固定搭配"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":49,"level":"B2","theme":"口语攻坚：正式陈述与辩论表达","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"本周词汇主战场是高频动词与万能表达（Les verbes fréquents et les expressions utiles）。先到 vocab.html#t25 把词表扫一遍，把 <span class=\"fr\" data-fr=\"disons que\">disons que</span>（可以说）、<span class=\"fr\" data-fr=\"enfin\">enfin</span>（也就是说）、<span class=\"fr\" data-fr=\"revenir sur\">revenir sur</span>（重新谈到）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5033","level":"B2","skill":"vocab","prompt":"« nuancer » 的意思是？","options":["补充细微差别","使麻木","宣布"],"answer":"补充细微差别","explain":"nuancer 是在表达中加入限定与细微差别；anesthésier 是麻醉；annoncer 是宣布。","source":"词汇 · 口语"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：un point de vue / nuancer","body":"把 <span class=\"fr\" data-fr=\"un point de vue\">un point de vue</span>（观点）和 <span class=\"fr\" data-fr=\"nuancer\">nuancer</span>（补充细微差别）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5034","level":"B2","skill":"vocab","prompt":"« un point de vue » 的意思是？","options":["观点","观景点","视力的点"],"answer":"观点","explain":"point de vue 在论述里指观点，也可以指观景处。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d35 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"conclure\">conclure</span>（总结；得出结论）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d35","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Disons que ce n'est pas la seule raison.\">Disons que ce n'est pas la seule raison.</span>（可以说这不是唯一的原因。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"disons que\">disons que</span> <span class=\"fr\" data-fr=\"enfin\">enfin</span> <span class=\"fr\" data-fr=\"revenir sur\">revenir sur</span> <span class=\"fr\" data-fr=\"un point de vue\">un point de vue</span> <span class=\"fr\" data-fr=\"nuancer\">nuancer</span> <span class=\"fr\" data-fr=\"conclure\">conclure</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · B2 高频固定搭配","type":"grammar","steps":[{"type":"grammar","title":"语法点：B2 高频固定搭配","body":"【B2 高频固定搭配】口语高分的技巧不是用难词，而是衔接自然：争取时间用 disons que、c'est-à-dire，自我修正用 enfin je veux dire，礼貌切换话题用 si vous me permettez, je reviendrai sur ce point。陈述时先给结论再补论据，比按时间顺序讲更符合考官期待。 例句：<span class=\"fr\" data-fr=\"Disons que ce n'est pas la seule raison.\">Disons que ce n'est pas la seule raison.</span>（可以说这不是唯一的原因。）；<span class=\"fr\" data-fr=\"Si vous me permettez, je reviendrai sur ce point.\">Si vous me permettez, je reviendrai sur ce point.</span>（如果您允许，我稍后再回到这一点。）。对照 grammar-b1b2.html#expressions-b2 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#expressions-b2","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5033","level":"B2","skill":"grammar","prompt":"口语中争取时间的说法是？","options":["Disons que…","Je ne sais pas.","Silence."],"answer":"Disons que…","explain":"disons que 用于思考时争取时间，同时保持句子的推进。","source":"口语 · 衔接技巧"},{"ref":"bank:grammar:B2:口语"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 B2 高频固定搭配 的规则和两个例句，再打开 grammar-b1b2.html#expressions-b2 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#expressions-b2","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5034","level":"B2","skill":"grammar","prompt":"「我想对这个点补充细微差别」应说？","options":["Je nuancerais ce point.","Je nuance ce point fort.","Je veux nuance."],"answer":"Je nuancerais ce point.","explain":"条件式 nuancerais 表示礼貌地补充与修正。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:B2:口语"}]},{"type":"read","title":"在短文里找B2 高频固定搭配","body":"在 grammar-b1b2.html#expressions-b2 的例句和章末小测里挑 5 句，圈出所有属于「B2 高频固定搭配」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#expressions-b2","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Disons que ce n'est pas la seule raison.\">Disons que ce n'est pas la seule raison.</span>（可以说这不是唯一的原因。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，B2 高频固定搭配 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：ce qui / ce que … c'est","body":"今天再回 grammar-b1b2.html#mer-cequi-cest 看一遍 ce qui / ce que … c'est，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#mer-cequi-cest","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:口语"}]}]},{"day":3,"theme":"精听 · 对话页的 d35 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d35 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d35","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5017","level":"B2","skill":"listening","prompt":"分析口语样题录音时，最该关注？","options":["考生如何开头、过渡与收尾","考生的口音","录音时长"],"answer":"考生如何开头、过渡与收尾","explain":"口语评分关注陈述结构与衔接，开头、过渡与收尾最能体现这一点。","source":"考试 · 口语策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:自行车道"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听 DELF B2 口语样题录音，分析考生如何组织陈述。","src":"dialogue.html#d35","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"disons que\">disons que</span>（可以说）、<span class=\"fr\" data-fr=\"enfin\">enfin</span>（也就是说）、<span class=\"fr\" data-fr=\"revenir sur\">revenir sur</span>（重新谈到）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「B2 高频固定搭配 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d35","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 正式陈述与辩论表达","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：按考试流程练 5 遍：30 分钟准备、10 分钟陈述并接受追问。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5009","level":"B2","skill":"speaking","prompt":"10 分钟陈述不冷场的关键是？","options":["准备一份 10 点提纲并练习过渡句","背下全文","说得越快越好"],"answer":"准备一份 10 点提纲并练习过渡句","explain":"提纲加过渡句能保证内容充足且衔接自然。","source":"口语 · 应试策略"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:禁止私家车"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d35 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、B2 高频固定搭配 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d35","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un point de vue\">un point de vue</span>（观点）、<span class=\"fr\" data-fr=\"nuancer\">nuancer</span>（补充细微差别）、<span class=\"fr\" data-fr=\"conclure\">conclure</span>（总结；得出结论）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 正式陈述与辩论表达","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读考试页口语专项与 6 个主题提纲。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5017","level":"B2","skill":"reading","prompt":"口语主题提纲应该写？","options":["关键词与例子，不写完整稿","完整成稿","只写标题"],"answer":"关键词与例子，不写完整稿","explain":"提纲只写关键词与例子，避免背稿导致的不自然。","source":"考试 · 口语准备"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:过度旅游"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「B2 高频固定搭配」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"disons que\">disons que</span>（可以说）、<span class=\"fr\" data-fr=\"enfin\">enfin</span>（也就是说）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#expressions-b2，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#expressions-b2","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:口语"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「B2 高频固定搭配」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 正式陈述与辩论表达","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：为 6 个主题各写一份 10 点提纲（不写完整稿）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5009","level":"B2","skill":"writing","prompt":"为 6 个主题写提纲的好处是？","options":["训练快速构思能力","减少练习时间","避免思考"],"answer":"训练快速构思能力","explain":"多个主题的提纲练习能提升即席构思的速度与质量。","source":"写作 · 提纲训练"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:禁用手机"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#expressions-b2，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#expressions-b2","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:口语"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「B2 高频固定搭配」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"disons que\">disons que</span>（可以说）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 正式陈述与辩论表达","type":"review","steps":[{"type":"review","title":"本周回顾：口语攻坚：正式陈述与辩论表达","body":"这一周围绕「口语攻坚：正式陈述与辩论表达」展开：语法主线是 B2 高频固定搭配，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 49 周清单逐条核对里程碑。","src":"calendar.html#wk-49","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：B2 高频固定搭配","body":"从 grammar-b1b2.html#expressions-b2 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#expressions-b2","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:口语"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"disons que\">disons que</span> <span class=\"fr\" data-fr=\"enfin\">enfin</span> <span class=\"fr\" data-fr=\"revenir sur\">revenir sur</span> <span class=\"fr\" data-fr=\"un point de vue\">un point de vue</span> <span class=\"fr\" data-fr=\"nuancer\">nuancer</span> <span class=\"fr\" data-fr=\"conclure\">conclure</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5035","level":"B2","skill":"vocab","prompt":"« conclure » 的意思是？","options":["总结；得出结论","包含","关闭"],"answer":"总结；得出结论","explain":"conclure 是总结、得出结论；inclure 是包含；clore 是关闭。","source":"词汇 · 论述"},{"id":"q-vocab-b2-5036","level":"B2","skill":"vocab","prompt":"« revenir sur » 的意思是？","options":["重新谈到","回到家里","反过来"],"answer":"重新谈到","explain":"revenir sur un point 表示重新谈到某一点。","source":"词汇 · 口语"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d35","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5018","level":"B2","skill":"listening","prompt":"听到 « enfin, je veux dire… » 时考生在做？","options":["自我修正","结束陈述","提出反驳"],"answer":"自我修正","explain":"这里的 enfin 表示修正，是口语里常见的自我更正标志。","source":"口语 · 衔接技巧"},{"id":"q-read-b2-5018","level":"B2","skill":"reading","prompt":"口语 6 个主题提纲的共同结构是？","options":["观点、论据、例子、结论","时间顺序","人物介绍"],"answer":"观点、论据、例子、结论","explain":"口语与写作的论述结构一致：观点、论据、例子、结论。","source":"考试 · 口语准备"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 B2 高频固定搭配 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#expressions-b2 再核对一次。","src":"grammar-b1b2.html#mer-cequi-cest","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5035","level":"B2","skill":"grammar","prompt":"「如果您允许，我稍后回到这一点」应说？","options":["Si vous me permettez, je reviendrai sur ce point.","Si vous me permettez, je reviens sur ce point hier.","Si vous permettez, je revenir sur ce point."],"answer":"Si vous me permettez, je reviendrai sur ce point.","explain":"礼貌征得同意用条件式 permettez，后续动作用简单将来时表示稍后要做。","source":"语法 · 条件式礼貌用法"},{"id":"q-gram-b2-5036","level":"B2","skill":"grammar","prompt":"「与其说这是缺点，不如说是特点」应说？","options":["Ce n'est pas tant un défaut qu'une particularité.","Ce n'est pas un défaut mais une particularité est.","Ce n'est pas tant un défaut comme une particularité."],"answer":"Ce n'est pas tant un défaut qu'une particularité.","explain":"ne pas tant… que 是对比结构，第二部分用 que。","source":"语法 · 固定搭配"},{"ref":"bank:grammar:B2:口语"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":50,"level":"B2","theme":"真实语料周：无字幕新闻、原版文章与语伴","days":[{"day":1,"theme":"词汇 · 媒体与娱乐","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：媒体与娱乐","body":"媒体与娱乐（Les médias et les loisirs）是这一周要反复见面的主题域。打开 vocab.html#t16，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un corpus\">un corpus</span>（语料）、<span class=\"fr\" data-fr=\"une expression\">une expression</span>（表达）、<span class=\"fr\" data-fr=\"un contexte\">un contexte</span>（语境）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t16","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5037","level":"B2","skill":"vocab","prompt":"« un contexte » 的意思是？","options":["语境","竞争","满意"],"answer":"语境","explain":"contexte 是语境、背景；concurrence 是竞争；contentement 是满意。","source":"词汇 · 语言学习"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"vocab","title":"搭配与辨析：reformuler / une nuance","body":"<span class=\"fr\" data-fr=\"reformuler\">reformuler</span>（改写）与 <span class=\"fr\" data-fr=\"une nuance\">une nuance</span>（细微差别）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t16","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5038","level":"B2","skill":"vocab","prompt":"« spontané » 的意思是？","options":["自然的；即兴的","自愿的","同时的"],"answer":"自然的；即兴的","explain":"spontané 指自然、即兴；volontaire 是自愿的；simultané 是同时的。","source":"词汇 · 口语"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"listen","title":"听音辨词：媒体与娱乐","body":"打开 对话页的 d34 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"spontané\">spontané</span>（自然的；即兴的）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d34","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il a plu, à la suite de quoi la route a été fermée.\">Il a plu, à la suite de quoi la route a été fermée.</span>（下过雨，随后道路被封闭了。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：媒体与娱乐 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un corpus\">un corpus</span> <span class=\"fr\" data-fr=\"une expression\">une expression</span> <span class=\"fr\" data-fr=\"un contexte\">un contexte</span> <span class=\"fr\" data-fr=\"reformuler\">reformuler</span> <span class=\"fr\" data-fr=\"une nuance\">une nuance</span> <span class=\"fr\" data-fr=\"spontané\">spontané</span>。说不出来的词立刻回到 vocab.html#t16 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t16","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]}]},{"day":2,"theme":"语法 · 复合关系代词与 où 扩展","type":"grammar","steps":[{"type":"grammar","title":"语法点：复合关系代词与 où 扩展","body":"【复合关系代词与 où 扩展】这一周从真实语料里收集 20 个「自己写不出来」的句子，逐句拆解结构，重点是介词加关系代词的组合（grâce auquel、à la suite de quoi）与分词短语。目标是用法语的思路取词，而不是先想中文再翻译。 例句：<span class=\"fr\" data-fr=\"Il a plu, à la suite de quoi la route a été fermée.\">Il a plu, à la suite de quoi la route a été fermée.</span>（下过雨，随后道路被封闭了。）；<span class=\"fr\" data-fr=\"C'est un sujet grâce auquel on comprend mieux la société.\">C'est un sujet grâce auquel on comprend mieux la société.</span>（这是一个能让人更好地理解社会的话题。）。对照 grammar-b1b2.html#rel-compose 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#rel-compose","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5037","level":"B2","skill":"grammar","prompt":"「随后道路被封闭」应说？","options":["Il a plu, à la suite de quoi la route a été fermée.","Il a plu, à la suite de que la route a été fermée.","Il a plu, suite de quoi la route a été fermée."],"answer":"Il a plu, à la suite de quoi la route a été fermée.","explain":"à la suite de quoi 是介词加关系代词的固定组合，用于连接前后事件。","source":"语法 · 复合关系代词"},{"ref":"bank:grammar:B2:复合关系"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#rel-compose 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Il a plu, à la suite de quoi la route a été fermée.\">Il a plu, à la suite de quoi la route a été fermée.</span>（下过雨，随后道路被封闭了。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#rel-compose","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5038","level":"B2","skill":"grammar","prompt":"指代工具时「通过它」应用？","options":["grâce auquel","grâce à que","grâce dont"],"answer":"grâce auquel","explain":"grâce à 加先行词时用 grâce auquel 或 grâce à laquelle。","source":"语法 · 复合关系代词"},{"ref":"bank:grammar:B2:复合关系"}]},{"type":"read","title":"在短文里找复合关系代词与 où 扩展","body":"在 grammar-b1b2.html#rel-compose 的例句和章末小测里挑 5 句，圈出所有属于「复合关系代词与 où 扩展」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#rel-compose","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il a plu, à la suite de quoi la route a été fermée.\">Il a plu, à la suite de quoi la route a été fermée.</span>（下过雨，随后道路被封闭了。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，复合关系代词与 où 扩展 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：分词式与从句互转","body":"今天再回 grammar-b1b2.html#participe-relative 看一遍 分词式与从句互转，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#participe-relative","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:复合关系"}]}]},{"day":3,"theme":"精听 · 对话页的 d34 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d34 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d34","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5019","level":"B2","skill":"listening","prompt":"无字幕新闻训练的正确做法是？","options":["先盲听再对照文字稿核对","先看文字稿再听","只听不核对"],"answer":"先盲听再对照文字稿核对","explain":"先盲听再核对文字稿，才能准确定位自己的理解盲点。","source":"考试 · 听力策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:四天工作制"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：每天 45 分钟无字幕法语新闻，记录 5 个新表达。","src":"dialogue.html#d34","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un corpus\">un corpus</span>（语料）、<span class=\"fr\" data-fr=\"une expression\">une expression</span>（表达）、<span class=\"fr\" data-fr=\"un contexte\">un contexte</span>（语境）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t16","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「复合关系代词与 où 扩展 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d34","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 无字幕新闻、原版文章与语伴","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：与语伴或 AI 进行 3 次 30 分钟真实对话，主题不做准备。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5010","level":"B2","skill":"speaking","prompt":"与语伴真实对话时，最大价值在于？","options":["被迫即席取词与自我修正","重复背过的句子","练习发音"],"answer":"被迫即席取词与自我修正","explain":"真实对话迫使你即席取词，这正是从翻译式表达走向法语思路的必经环节。","source":"口语 · 输出训练"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:远程办公"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d34 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、复合关系代词与 où 扩展 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d34","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"reformuler\">reformuler</span>（改写）、<span class=\"fr\" data-fr=\"une nuance\">une nuance</span>（细微差别）、<span class=\"fr\" data-fr=\"spontané\">spontané</span>（自然的；即兴的）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t16 再看一遍例句。","src":"vocab.html#t16","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 无字幕新闻、原版文章与语伴","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 3 篇原版长文（报纸社论、杂志长报道、短篇小说一章）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5019","level":"B2","skill":"reading","prompt":"读原版长文时，遇到「写不出来的句子」应该？","options":["整句抄下并拆解结构","只查生词","直接跳过"],"answer":"整句抄下并拆解结构","explain":"收集自己写不出来的句子并拆解结构，是把被动理解转化为主动表达的高效方法。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:过度旅游"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un corpus\">un corpus</span>（语料）、<span class=\"fr\" data-fr=\"une expression\">une expression</span>（表达）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t16","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#rel-compose，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#rel-compose","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:复合关系"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「复合关系代词与 où 扩展」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 无字幕新闻、原版文章与语伴","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词长文摘要加个人评论。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5010","level":"B2","skill":"writing","prompt":"300 词摘要加评论的结构是？","options":["先摘要后评论，用过渡句分开","只写摘要","只写评论"],"answer":"先摘要后评论，用过渡句分开","explain":"摘要与评论要分开，用过渡句标明从客观到主观的转换。","source":"写作 · 摘要与评论"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:免费停车"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#rel-compose，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#rel-compose","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:复合关系"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「复合关系代词与 où 扩展」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un corpus\">un corpus</span>（语料）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 无字幕新闻、原版文章与语伴","type":"review","steps":[{"type":"review","title":"本周回顾：真实语料周：无字幕新闻、原版文章与语伴","body":"这一周围绕「真实语料周：无字幕新闻、原版文章与语伴」展开：语法主线是 复合关系代词与 où 扩展，词汇主线是 媒体与娱乐。先用 3 句话口头复述本周学了什么，再打开日历页第 50 周清单逐条核对里程碑。","src":"calendar.html#wk-50","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"语法复盘：复合关系代词与 où 扩展","body":"从 grammar-b1b2.html#rel-compose 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#rel-compose","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:复合关系"}]},{"type":"review","title":"词汇自测：媒体与娱乐","body":"遮住中文看 vocab.html#t16 的 6 个核心词：<span class=\"fr\" data-fr=\"un corpus\">un corpus</span> <span class=\"fr\" data-fr=\"une expression\">une expression</span> <span class=\"fr\" data-fr=\"un contexte\">un contexte</span> <span class=\"fr\" data-fr=\"reformuler\">reformuler</span> <span class=\"fr\" data-fr=\"une nuance\">une nuance</span> <span class=\"fr\" data-fr=\"spontané\">spontané</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t16","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5039","level":"B2","skill":"vocab","prompt":"« un corpus » 的意思是？","options":["语料","身体","团体"],"answer":"语料","explain":"corpus 指收集起来的语料；corps 是身体，也可以指团体。","source":"词汇 · 语言学习"},{"id":"q-vocab-b2-5040","level":"B2","skill":"vocab","prompt":"« une nuance » 的意思是？","options":["细微差别","云朵","新意"],"answer":"细微差别","explain":"nuance 指细微差别；nuage 是云；nouveauté 是新意。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d34","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5020","level":"B2","skill":"listening","prompt":"新闻报道里的立场常通过什么体现？","options":["选词与主动被动的选择","语速","主播性别"],"answer":"选词与主动被动的选择","explain":"选词与句式（尤其主动被动）是媒体立场的隐性载体，值得专门记录。","source":"考试 · 听力策略"},{"id":"q-read-b2-5020","level":"B2","skill":"reading","prompt":"« ce dont il s'agit » 的意思是？","options":["所涉及的事情","他同意的事","他做的事"],"answer":"所涉及的事情","explain":"s'agir de 加先行词时用 ce dont il s'agit，是书面语里的高频结构。","source":"语法 · 关系代词"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 复合关系代词与 où 扩展 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#rel-compose 再核对一次。","src":"grammar-b1b2.html#participe-relative","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5039","level":"B2","skill":"grammar","prompt":"「这是一个能理解社会的话题」应说？","options":["C'est un sujet grâce auquel on comprend la société.","C'est un sujet grâce à que on comprend la société.","C'est un sujet dont on comprend la société."],"answer":"C'est un sujet grâce auquel on comprend la société.","explain":"comprendre grâce à 需要 à 加先行词，用 grâce auquel。","source":"语法 · 复合关系代词"},{"id":"q-gram-b2-5040","level":"B2","skill":"grammar","prompt":"把「因为下雨，活动被取消」改写成分词结构？","options":["La pluie ayant empêché l'activité, celle-ci a été annulée.","La pluie a empêché, l'activité annulée.","La pluie empêchant, l'activité est annulée hier."],"answer":"La pluie ayant empêché l'activité, celle-ci a été annulée.","explain":"复合过去分词（ayant 加过去分词）可以表示原因与先时性，是压缩句子的常用手段。","source":"语法 · 复合过去分词"},{"ref":"bank:grammar:B2:复合关系"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":51,"level":"B2","theme":"全真模考周（一）：DELF B2 完整模拟与批改","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"une consigne\">une consigne</span>（题目要求）、<span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span>（草稿）、<span class=\"fr\" data-fr=\"un barème\">un barème</span>（评分表）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5041","level":"B2","skill":"vocab","prompt":"« une consigne » 的意思是？","options":["题目要求","建议","惩罚"],"answer":"题目要求","explain":"consigne 指题目要求或指令；conseil 是建议；sanction 是惩罚。","source":"词汇 · 考试"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：une échéance / gérer","body":"把 <span class=\"fr\" data-fr=\"une échéance\">une échéance</span>（截止时间）和 <span class=\"fr\" data-fr=\"gérer\">gérer</span>（管理；应对）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5042","level":"B2","skill":"vocab","prompt":"« un barème » 的意思是？","options":["评分表","气压计","男爵"],"answer":"评分表","explain":"barème 是评分标准表；baromètre 是气压计；baron 是男爵。","source":"词汇 · 考试"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d35 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"relire\">relire</span>（重读检查）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d35","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Le sujet exige que l'on prenne position.\">Le sujet exige que l'on prenne position.</span>（这个题目要求我们表明立场。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une consigne\">une consigne</span> <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span> <span class=\"fr\" data-fr=\"un barème\">un barème</span> <span class=\"fr\" data-fr=\"une échéance\">une échéance</span> <span class=\"fr\" data-fr=\"gérer\">gérer</span> <span class=\"fr\" data-fr=\"relire\">relire</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · si 的三种假设句型","type":"grammar","steps":[{"type":"grammar","title":"语法点：si 的三种假设句型","body":"【si 的三种假设句型】这一周严格按考试时间表完成一整套 DELF B2 模拟：听力 30 分钟、阅读 60 分钟、写作 60 分钟、口语准备 30 分钟加考试 20 分钟。做完按评分标准逐项打分，错题按听力、阅读、写作、口语分类，再定「语速、词汇、推理、结构、语法」五类对策。 例句：<span class=\"fr\" data-fr=\"Le sujet exige que l'on prenne position.\">Le sujet exige que l'on prenne position.</span>（这个题目要求我们表明立场。）；<span class=\"fr\" data-fr=\"Si j'avais disposé de plus de temps, j'aurais développé cet argument.\">Si j'avais disposé de plus de temps, j'aurais développé cet argument.</span>（要是我有更多时间，就会把这个论点展开。）。对照 grammar-b1b2.html#si-trois 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#si-trois","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5041","level":"B2","skill":"grammar","prompt":"「这个题目要求我们表明立场」应说？","options":["Le sujet exige que l'on prenne position.","Le sujet exige que l'on prend position.","Le sujet exige de prendre position que."],"answer":"Le sujet exige que l'on prenne position.","explain":"exiger que 后接虚拟式，prendre 的形式是 prenne。","source":"语法 · 虚拟式"},{"ref":"bank:grammar:B2:假设"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 si 的三种假设句型 的规则和两个例句，再打开 grammar-b1b2.html#si-trois 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#si-trois","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5042","level":"B2","skill":"grammar","prompt":"「要是我有更多时间，就会展开这个论点」应说？","options":["Si j'avais disposé de plus de temps, j'aurais développé cet argument.","Si j'aurais disposé de plus de temps, j'aurais développé cet argument.","Si j'avais disposé de plus de temps, je développais cet argument."],"answer":"Si j'avais disposé de plus de temps, j'aurais développé cet argument.","explain":"第三型假设：si 从句用愈过去时，主句用条件式过去时。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B2:假设"}]},{"type":"read","title":"在短文里找si 的三种假设句型","body":"在 grammar-b1b2.html#si-trois 的例句和章末小测里挑 5 句，圈出所有属于「si 的三种假设句型」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#si-trois","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Le sujet exige que l'on prenne position.\">Le sujet exige que l'on prenne position.</span>（这个题目要求我们表明立场。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，si 的三种假设句型 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：虚拟式过去时","body":"今天再回 grammar-b1b2.html#subj-passe 看一遍 虚拟式过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#subj-passe","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:假设"}]}]},{"day":3,"theme":"精听 · 对话页的 d35 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d35 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d35","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5021","level":"B2","skill":"listening","prompt":"听完材料立刻誊写答案的原因是？","options":["考试不允许回听，先定答案更稳","字迹会变差","节省墨水"],"answer":"考试不允许回听，先定答案更稳","explain":"真实考试中听力只放一到两遍且不能回听，及时定答案是最优策略。","source":"考试 · 听力策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:一次性塑料"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：按考试时间做听力 30 分钟，听完立刻誊写答案，不回头改。","src":"dialogue.html#d35","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une consigne\">une consigne</span>（题目要求）、<span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span>（草稿）、<span class=\"fr\" data-fr=\"un barème\">un barème</span>（评分表）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「si 的三种假设句型 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d35","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · DELF B2 完整模拟与批改","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：完整做一遍口语：30 分钟准备加 20 分钟考试，全程录音。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5011","level":"B2","skill":"speaking","prompt":"模考口语录音后最该做的是？","options":["按评分表逐项自评并重录","只统计时长","删掉录音"],"answer":"按评分表逐项自评并重录","explain":"按评分表自评并重录，才能把模考转化为能力提升。","source":"考试 · 口语策略"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:人工智能"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d35 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、si 的三种假设句型 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d35","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une échéance\">une échéance</span>（截止时间）、<span class=\"fr\" data-fr=\"gérer\">gérer</span>（管理；应对）、<span class=\"fr\" data-fr=\"relire\">relire</span>（重读检查）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · DELF B2 完整模拟与批改","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：限时做阅读 60 分钟，做完统计同义替换与推理题的正确率。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5021","level":"B2","skill":"reading","prompt":"阅读模考后统计「同义替换」正确率的目的是？","options":["定位词汇与推理的薄弱点","计算总时长","评估文章难度"],"answer":"定位词汇与推理的薄弱点","explain":"按题型统计正确率能精确指出薄弱环节，指导后续训练。","source":"考试 · 复盘方法"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:一次性塑料"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「si 的三种假设句型」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une consigne\">une consigne</span>（题目要求）、<span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span>（草稿）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#si-trois，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#si-trois","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:假设"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「si 的三种假设句型」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · DELF B2 完整模拟与批改","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：限时写两篇文章（各 250 词），60 分钟内完成。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5011","level":"B2","skill":"writing","prompt":"60 分钟完成两篇 250 词文章的关键是？","options":["每篇先花 5 分钟列提纲","先写后改结构","边写边查词典"],"answer":"每篇先花 5 分钟列提纲","explain":"先列提纲能避免写到一半推翻结构，是限时写作最重要的习惯。","source":"写作 · 应试策略"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:投诉信"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#si-trois，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#si-trois","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:假设"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「si 的三种假设句型」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une consigne\">une consigne</span>（题目要求）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · DELF B2 完整模拟与批改","type":"review","steps":[{"type":"review","title":"本周回顾：全真模考周（一）：DELF B2 完整模拟与批改","body":"这一周围绕「全真模考周（一）：DELF B2 完整模拟与批改」展开：语法主线是 si 的三种假设句型，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 51 周清单逐条核对里程碑。","src":"calendar.html#wk-51","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：si 的三种假设句型","body":"从 grammar-b1b2.html#si-trois 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#si-trois","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:假设"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"une consigne\">une consigne</span> <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span> <span class=\"fr\" data-fr=\"un barème\">un barème</span> <span class=\"fr\" data-fr=\"une échéance\">une échéance</span> <span class=\"fr\" data-fr=\"gérer\">gérer</span> <span class=\"fr\" data-fr=\"relire\">relire</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5043","level":"B2","skill":"vocab","prompt":"« gérer » 的意思是？","options":["管理；应对","总经理","保证"],"answer":"管理；应对","explain":"gérer 是管理、应对；gérant 是管理者；garantir 是保证。","source":"词汇 · 职场"},{"id":"q-vocab-b2-5044","level":"B2","skill":"vocab","prompt":"« relire » 的意思是？","options":["重读检查","重新连接","再选一次"],"answer":"重读检查","explain":"relire 指写完后再读一遍检查；relier 是连接。","source":"词汇 · 写作"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d35","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5022","level":"B2","skill":"listening","prompt":"听力错因里「推理」类问题指？","options":["需要在听懂的基础上推断言外之意","没听清单词","语速太快"],"answer":"需要在听懂的基础上推断言外之意","explain":"推理题要求结合语境推断说话人的态度或意图，是 B2 听力的高阶要求。","source":"考试 · 听力策略"},{"id":"q-read-b2-5022","level":"B2","skill":"reading","prompt":"考试时间表里阅读的时间是？","options":["60 分钟","30 分钟","45 分钟"],"answer":"60 分钟","explain":"DELF B2 的阅读为 60 分钟，听力 30 分钟，写作 60 分钟。","source":"考试 · 考试结构"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 si 的三种假设句型 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#si-trois 再核对一次。","src":"grammar-b1b2.html#subj-passe","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5043","level":"B2","skill":"grammar","prompt":"「无论结果如何，我都要再练一遍」应说？","options":["Quel que soit le résultat, je recommencerai.","Quel que le résultat soit, je recommencerai.","Quoi que soit le résultat, je recommencerai."],"answer":"Quel que soit le résultat, je recommencerai.","explain":"quel que soit 加名词是固定顺序，quel 要与名词性数配合。","source":"语法 · 让步"},{"id":"q-gram-b2-5044","level":"B2","skill":"grammar","prompt":"「我后悔没能早点开始」应说？","options":["Je regrette de ne pas avoir commencé plus tôt.","Je regrette que je ne commence pas plus tôt.","Je regrette de ne pas commencer plus tôt."],"answer":"Je regrette de ne pas avoir commencé plus tôt.","explain":"同一主语时 regretter 后接 de 加不定式过去时，不需要虚拟式从句。","source":"语法 · 不定式过去时"},{"ref":"bank:grammar:B2:假设"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":52,"level":"B2","theme":"全真模考周（二）+ 年度总结与后续路线","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"高频动词与万能表达（Les verbes fréquents et les expressions utiles）是这一周要反复见面的主题域。打开 vocab.html#t25，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un bilan\">un bilan</span>（总结；盘点）、<span class=\"fr\" data-fr=\"un portfolio\">un portfolio</span>（作品集）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5045","level":"B2","skill":"vocab","prompt":"« un bilan » 的意思是？","options":["总结；盘点","天平","账单"],"answer":"总结；盘点","explain":"bilan 指总结、盘点，也指体检结果；balance 是天平。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：une progression / persévérer","body":"<span class=\"fr\" data-fr=\"une progression\">une progression</span>（进步；进展）与 <span class=\"fr\" data-fr=\"persévérer\">persévérer</span>（坚持）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5046","level":"B2","skill":"vocab","prompt":"« persévérer » 的意思是？","options":["坚持","穿透","劝阻"],"answer":"坚持","explain":"persévérer 是坚持不懈；pénétrer 是穿透；dissuader 是劝阻。","source":"词汇 · 学习"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d40 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"viser\">viser</span>（瞄准；旨在）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d40","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Cette année, j'ai appris à penser en français.\">Cette année, j'ai appris à penser en français.</span>（这一年，我学会了用法语思考。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un bilan\">un bilan</span> <span class=\"fr\" data-fr=\"un portfolio\">un portfolio</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"une progression\">une progression</span> <span class=\"fr\" data-fr=\"persévérer\">persévérer</span> <span class=\"fr\" data-fr=\"viser\">viser</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · 时态配合","type":"grammar","steps":[{"type":"grammar","title":"语法点：时态配合","body":"【时态配合】最后一周再做一套全新模拟卷，目标总分不低于 55、单项均不低于 11 分。年度盘点要统计学习小时、词量、作文篇数与录音时长，整理 12 篇最佳写作与 6 段最佳录音作为作品集，并列出与 B2 在听、说、读、写、文化五项上的具体差距。 例句：<span class=\"fr\" data-fr=\"Cette année, j'ai appris à penser en français.\">Cette année, j'ai appris à penser en français.</span>（这一年，我学会了用法语思考。）；<span class=\"fr\" data-fr=\"L'année prochaine, je viserai le niveau C1.\">L'année prochaine, je viserai le niveau C1.</span>（明年我要冲击 C1。）。对照 grammar-b1b2.html#concordance 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#concordance","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5045","level":"B2","skill":"grammar","prompt":"「这一年我学会了用法语思考」应说？","options":["Cette année, j'ai appris à penser en français.","Cette année, j'ai appris penser en français.","Cette année, j'apprenais à penser en français."],"answer":"Cette année, j'ai appris à penser en français.","explain":"apprendre 后接 à 加不定式；谈论已完成的收获用复合过去时。","source":"语法 · 复合过去时"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#concordance 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Cette année, j'ai appris à penser en français.\">Cette année, j'ai appris à penser en français.</span>（这一年，我学会了用法语思考。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#concordance","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5046","level":"B2","skill":"grammar","prompt":"「明年我要冲击 C1」应说？","options":["L'année prochaine, je viserai le C1.","L'année prochaine, je vise le C1 l'an dernier.","L'année prochaine, je visais le C1."],"answer":"L'année prochaine, je viserai le C1.","explain":"明确的将来计划用简单将来时。","source":"语法 · 简单将来时"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"read","title":"在短文里找时态配合","body":"在 grammar-b1b2.html#concordance 的例句和章末小测里挑 5 句，圈出所有属于「时态配合」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#concordance","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Cette année, j'ai appris à penser en français.\">Cette année, j'ai appris à penser en français.</span>（这一年，我学会了用法语思考。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，时态配合 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：书面语体特征","body":"今天再回 grammar-b1b2.html#nom-style 看一遍 书面语体特征，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#nom-style","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:书面语体"}]}]},{"day":3,"theme":"精听 · 对话页的 d40 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d40 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d40","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5023","level":"B2","skill":"listening","prompt":"对比第 51 周与第 52 周听力成绩的意义是？","options":["确认进步是否稳定","统计错题数量","评估试卷难度"],"answer":"确认进步是否稳定","explain":"两次模考的对比能区分真实进步与试卷难度波动。","source":"考试 · 复盘方法"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:自行车道"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：做一套全新模拟卷的听力部分（30 分钟），对比第 51 周的成绩。","src":"dialogue.html#d40","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un bilan\">un bilan</span>（总结；盘点）、<span class=\"fr\" data-fr=\"un portfolio\">un portfolio</span>（作品集）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「时态配合 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d40","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 全真模考周（二）+ 年度总结与后续路线","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：录一段 10 分钟年度自述（我的法语这一年），保存为里程碑。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5012","level":"B2","skill":"speaking","prompt":"年度自述最值得保留的内容是？","options":["一年的关键转折与具体进步","个人隐私细节","抱怨学习辛苦"],"answer":"一年的关键转折与具体进步","explain":"年度自述聚焦具体进步与转折，才有作为作品集的价值。","source":"口语 · 自述"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:心理健康"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d40 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、时态配合 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d40","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une progression\">une progression</span>（进步；进展）、<span class=\"fr\" data-fr=\"persévérer\">persévérer</span>（坚持）、<span class=\"fr\" data-fr=\"viser\">viser</span>（瞄准；旨在）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 全真模考周（二）+ 年度总结与后续路线","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 1500 词原版长文，限时 15 分钟完成主旨与细节题。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5023","level":"B2","skill":"reading","prompt":"年度最后一次阅读训练应该重点练？","options":["限时定位与主旨判断","逐词翻译","背单词"],"answer":"限时定位与主旨判断","explain":"考前的阅读训练应以限时定位与主旨判断为主，保持手感。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:人工智能"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un bilan\">un bilan</span>（总结；盘点）、<span class=\"fr\" data-fr=\"un portfolio\">un portfolio</span>（作品集）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#concordance，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#concordance","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「时态配合」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 全真模考周（二）+ 年度总结与后续路线","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词年度总结（收获、差距、后续路线），保存进作品集。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5012","level":"B2","skill":"writing","prompt":"年度总结里的「差距分析」应该写？","options":["每项能力各两条具体改进动作","只说不足","只写成绩"],"answer":"每项能力各两条具体改进动作","explain":"差距分析要落到可执行的改进动作，否则只是情绪记录。","source":"写作 · 年度总结"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:四天工作制"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#concordance，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#concordance","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「时态配合」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un bilan\">un bilan</span>（总结；盘点）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 全真模考周（二）+ 年度总结与后续路线","type":"review","steps":[{"type":"review","title":"本周回顾：全真模考周（二）+ 年度总结与后续路线","body":"这一周围绕「全真模考周（二）+ 年度总结与后续路线」展开：语法主线是 时态配合，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 52 周清单逐条核对里程碑。","src":"calendar.html#wk-52","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：时态配合","body":"从 grammar-b1b2.html#concordance 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#concordance","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"un bilan\">un bilan</span> <span class=\"fr\" data-fr=\"un portfolio\">un portfolio</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"une progression\">une progression</span> <span class=\"fr\" data-fr=\"persévérer\">persévérer</span> <span class=\"fr\" data-fr=\"viser\">viser</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5047","level":"B2","skill":"vocab","prompt":"« une progression » 的意思是？","options":["进步；进展","程序","项目"],"answer":"进步；进展","explain":"progression 指进步或进展过程；programme 是程序；projet 是项目。","source":"词汇 · 学习"},{"id":"q-vocab-b2-5048","level":"B2","skill":"vocab","prompt":"« un portfolio » 的意思是？","options":["作品集","投资组合文件袋","港口"],"answer":"作品集","explain":"portfolio 在语言学习里指作品集，在金融里指投资组合。","source":"词汇 · 学习"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d40","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5024","level":"B2","skill":"listening","prompt":"两次模考成绩接近时，最该做的是？","options":["逐项比较单项得分找短板","认定自己没进步","换一套更难的卷子"],"answer":"逐项比较单项得分找短板","explain":"总分相近时，单项得分的结构变化才是关键信息。","source":"考试 · 复盘方法"},{"id":"q-read-b2-5024","level":"B2","skill":"reading","prompt":"「单项不低于 11 分」对应的总分目标大约是？","options":["55 分左右","50 分","25 分"],"answer":"55 分左右","explain":"DELF B2 四个单项各 25 分，单项 11 分左右、总分 55 分是稳妥目标；及格线是总分 50 且单项不低于 5。","source":"考试 · 考试结构"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 时态配合 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#concordance 再核对一次。","src":"grammar-b1b2.html#nom-style","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5047","level":"B2","skill":"grammar","prompt":"「如果这一年没有坚持，我不会达到这个水平」应说？","options":["Si je n'avais pas persévéré, je n'aurais pas atteint ce niveau.","Si je n'ai pas persévéré, je n'aurais pas atteint ce niveau.","Si je ne persévérais pas, je n'atteindrais pas ce niveau hier."],"answer":"Si je n'avais pas persévéré, je n'aurais pas atteint ce niveau.","explain":"第三型假设：si 从句用愈过去时，主句用条件式过去时。","source":"语法 · 假设三型"},{"id":"q-gram-b2-5048","level":"B2","skill":"grammar","prompt":"年度语法速查表里，时态配合的三条规则是？","options":["同时用未完成过去时、先时用愈过去时、后时用条件式","一律用现在时","一律用简单将来时"],"answer":"同时用未完成过去时、先时用愈过去时、后时用条件式","explain":"主句过去时时，从句按同时、先时、后时分别使用未完成过去时、愈过去时与条件式。","source":"语法 · 时态配合"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]}];
